from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            cells = []
            seeds = set()
            while q:
                y,x=q.popleft()
                cells.append((y,x))
                if grid[y][x] not in (0,1): seeds.add(grid[y][x])
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]!=0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            if len(seeds)==1:
                color=next(iter(seeds))
                for y,x in cells:
                    if all(0<=yy<h and 0<=xx<w and grid[yy][xx]!=0
                           for yy in range(y-1,y+2) for xx in range(x-1,x+2)):
                        out[y][x]=color
    return out
